<!--
  下拉选择 (bits-ui)。

  选项面板经 `Select.Portal` 挂到 `body`: 对话框正文/设置页都是 `overflow: auto` 的滚动容器,
  就地渲染的菜单会被祖先裁掉, 只露出半截。port 到 body 之后菜单不受任何祖先裁剪, 靠近视口边缘
  时由 floating-ui 自动翻转。外观沿用既有类名 (`.select` / `.select-trigger` / `.select-menu`)。
-->

<script lang="ts">
  import { Select } from 'bits-ui';

  import Icon from './Icon.svelte';

  export interface SelectOption {
    value: string;
    label: string;
  }

  let {
    value = $bindable(''),
    options,
    onchange,
    /** 无障碍标签与悬浮提示 */
    title,
    disabled = false,
    /** 值不在选项里时的占位文案 */
    placeholder,
    className = '',
  }: {
    value?: string;
    options: SelectOption[];
    onchange?: (value: string) => void;
    title?: string;
    disabled?: boolean;
    placeholder?: string;
    className?: string;
  } = $props();

  /*
   * 选中的标签三级回退: 选项里有就用选项文案; 值不在选项里 (值可能来自旧设置或后端) 就原样显示
   * 值本身; 连值都没有才用占位文案。**空串也当成没有值** —— 少了这一级会让"设置里存着一个已不在
   * 候选里的值"显示成空白 (角色 / 权重那几个下拉靠它显示占位)。
   */
  const selectedLabel = $derived(
    options.find((option) => option.value === value)?.label ?? (value || undefined) ?? placeholder ?? ''
  );

  /** 触发按钮元素: 只用来量宽度, 让菜单与触发器等宽。 */
  let triggerEl = $state<HTMLButtonElement | null>(null);

  /* 菜单与触发按钮**等宽**。菜单走 portal (见模板), 由 floating-ui 定位成 `position: fixed`,
     所以 CSS 的 `width: 100%` 会按视口算 —— 只能量出来写进去。 */
  let triggerWidth = $state(0);

  $effect(() => {
    const el = triggerEl;
    if (!el) return;
    const measure = () => (triggerWidth = el.offsetWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  });
</script>

<div class="select {className}">
  <Select.Root
    type="single"
    {disabled}
    {value}
    onValueChange={(next) => {
      if (next === undefined) return;
      value = next;
      onchange?.(next);
    }}
  >
    <Select.Trigger bind:ref={triggerEl} class="select-trigger" {title} aria-label={title ?? selectedLabel}>
      <span class="select-value">{selectedLabel}</span>
      <Icon name="ChevronDown" size={14} />
    </Select.Trigger>

    <!--
      菜单挂到 `body` 上 (portal): 对话框正文与设置页都是 `overflow: auto` 的滚动容器,
      就地渲染的菜单会被它们裁掉 (选项只露出一半, 甚至完全看不见)。portal + floating-ui 的
      `position: fixed` 让菜单永远浮在最上层, 靠近边缘时还会自动翻转。
      `collisionPadding` 留 8px: 贴着视口边缘弹出的菜单看起来像被裁掉了。可用高度由 bits-ui 的
      `size` 中间件挂在 `--bits-floating-available-height` 上, `.select-menu` 用它兜住最大高度。
    -->
    <Select.Portal>
      <Select.Content
        class="select-menu"
        sideOffset={4}
        collisionPadding={8}
        style={triggerWidth ? `width:${triggerWidth}px` : undefined}
      >
        {#each options as option (option.value)}
          <Select.Item class="select-option" value={option.value} label={option.label}>
            {option.label}
          </Select.Item>
        {/each}
      </Select.Content>
    </Select.Portal>
  </Select.Root>
</div>
